"""Tests for synthstr.stringy — string helper utilities."""

from __future__ import annotations

import pytest

from synthstr.stringy import is_palindrome, reverse, truncate, word_count


# ── reverse ──────────────────────────────────────────────────────────


class TestReverse:
    @pytest.mark.parametrize(
        "input_str, expected",
        [
            ("hello", "olleh"),
            ("abcdef", "fedcba"),
            ("a", "a"),
            ("", ""),
            ("racecar", "racecar"),  # palindrome stays the same
        ],
        ids=["basic", "longer", "single-char", "empty", "palindrome"],
    )
    def test_reverse_produces_expected_output(self, input_str: str, expected: str):
        assert reverse(input_str) == expected

    def test_reverse_unicode(self):
        assert reverse("café") == "éfac"

    def test_reverse_with_spaces_and_punctuation(self):
        assert reverse("a b!") == "!b a"

    def test_reverse_is_own_inverse(self):
        s = "hello world"
        assert reverse(reverse(s)) == s

    def test_reverse_preserves_length(self):
        s = "testing"
        assert len(reverse(s)) == len(s)


# ── is_palindrome ───────────────────────────────────────────────────


class TestIsPalindrome:
    @pytest.mark.parametrize(
        "input_str",
        [
            "racecar",
            "madam",
            "A man, a plan, a canal: Panama",
            "Was it a car or a cat I saw?",
            "",
            "a",
        ],
        ids=[
            "simple",
            "odd-length",
            "classic-sentence",
            "question-punctuation",
            "empty",
            "single-char",
        ],
    )
    def test_palindromes_return_true(self, input_str: str):
        assert is_palindrome(input_str) is True

    @pytest.mark.parametrize(
        "input_str",
        [
            "hello",
            "python",
            "ab",
            "almost racecar!x",
        ],
        ids=["basic", "longer", "two-char", "near-palindrome"],
    )
    def test_non_palindromes_return_false(self, input_str: str):
        assert is_palindrome(input_str) is False

    def test_ignores_case(self):
        assert is_palindrome("RaceCar") is True

    def test_ignores_non_alphanumeric(self):
        assert is_palindrome("!@#a#@!") is True

    def test_digits_treated_as_alphanumeric(self):
        assert is_palindrome("12321") is True
        assert is_palindrome("12345") is False

    def test_only_non_alphanumeric_chars(self):
        # Cleaned string is empty → trivially a palindrome
        assert is_palindrome("!!!...") is True


# ── word_count ───────────────────────────────────────────────────────


class TestWordCount:
    @pytest.mark.parametrize(
        "input_str, expected",
        [
            ("hello world", 2),
            ("one", 1),
            ("", 0),
            ("  leading and trailing  ", 3),
            ("multiple   spaces   between", 3),
            ("tab\tseparated\twords", 3),
            ("newline\nseparated", 2),
        ],
        ids=[
            "two-words",
            "single-word",
            "empty",
            "leading-trailing-spaces",
            "multiple-spaces",
            "tabs",
            "newlines",
        ],
    )
    def test_word_count(self, input_str: str, expected: int):
        assert word_count(input_str) == expected

    def test_whitespace_only(self):
        assert word_count("   ") == 0


# ── truncate ─────────────────────────────────────────────────────────


class TestTruncate:
    def test_no_truncation_when_within_limit(self):
        assert truncate("hello", 10) == "hello"

    def test_no_truncation_at_exact_limit(self):
        assert truncate("hello", 5) == "hello"

    def test_truncation_adds_ellipsis(self):
        result = truncate("hello world", 6)
        assert result == "hello\u2026"
        assert len(result) == 6

    def test_truncation_to_one(self):
        result = truncate("hello", 1)
        assert result == "\u2026"
        assert len(result) == 1

    def test_truncation_to_zero(self):
        assert truncate("hello", 0) == ""

    def test_negative_limit_raises(self):
        with pytest.raises(ValueError, match="limit must be non-negative"):
            truncate("hello", -1)

    def test_empty_string_within_any_limit(self):
        assert truncate("", 0) == ""
        assert truncate("", 5) == ""

    @pytest.mark.parametrize(
        "limit",
        [2, 3, 5, 8],
    )
    def test_result_never_exceeds_limit(self, limit: int):
        s = "a long string that should be truncated"
        assert len(truncate(s, limit)) <= limit

    def test_truncation_preserves_prefix(self):
        result = truncate("abcdef", 4)
        assert result[:3] == "abc"
        assert result[3] == "\u2026"

